    #[test]
    fn a_node_of_several_operands_stops_where_sigmastate_stops() {
        let wrong = wrong_rows(SEVERAL_OPERANDS);
        assert!(
            wrong.is_empty(),
            "{} of {} rows:\n{}",
            wrong.len(),
            SEVERAL_OPERANDS.len(),
            wrong.join("\n")
        );
    }
